import{_ as e,a as d,o,a4 as a}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse(`{"title":"Products","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-products-list","title":"List Products (datagrid)","description":"The full Catalog → Products datagrid. Cursor pagination via first / after. All scalar fields (including special-price) resolve over GraphQL; relation blocks are detail-only (query them on the single-product query).","query":"query AdminCatalogProducts($first: Int, $after: String, $status: Int, $sort: String, $order: String) {\\n  adminCatalogProducts(first: $first, after: $after, status: $status, sort: $sort, order: $order) {\\n    edges {\\n      cursor\\n      node {\\n        id _id sku name type status\\n        price formattedPrice\\n        specialPrice formattedSpecialPrice specialPriceFrom specialPriceTo\\n        quantity baseImageUrl categoryName\\n        channel locale attributeFamilyId attributeFamilyName\\n        urlKey visibleIndividually featured new createdAt updatedAt\\n      }\\n    }\\n    pageInfo { hasNextPage endCursor }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 1,\\n  \\"status\\": 1,\\n  \\"sort\\": \\"id\\",\\n  \\"order\\": \\"asc\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCatalogProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/products/1\\",\\n            \\"_id\\": 1,\\n            \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n            \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n            \\"type\\": \\"simple\\",\\n            \\"status\\": 1,\\n            \\"price\\": \\"100.0000\\",\\n            \\"formattedPrice\\": \\"$100.00\\",\\n            \\"specialPrice\\": null,\\n            \\"formattedSpecialPrice\\": null,\\n            \\"specialPriceFrom\\": null,\\n            \\"specialPriceTo\\": null,\\n            \\"quantity\\": 10000,\\n            \\"baseImageUrl\\": \\"http://localhost:8000/storage/product/1/zKcWZTLDjcawJmaNg8g1cpARqwVONgEKEflabstT.webp\\",\\n            \\"categoryName\\": \\"Fashion\\",\\n            \\"channel\\": \\"default\\",\\n            \\"locale\\": \\"en\\",\\n            \\"attributeFamilyId\\": 1,\\n            \\"attributeFamilyName\\": \\"Default\\",\\n            \\"urlKey\\": \\"coastal-breeze-mens-blue-zipper-hoodie\\",\\n            \\"visibleIndividually\\": true,\\n            \\"featured\\": true,\\n            \\"new\\": true,\\n            \\"createdAt\\": \\"2024-04-16 17:32:38\\",\\n            \\"updatedAt\\": \\"2026-04-07 15:20:30\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": { \\"hasNextPage\\": true, \\"endCursor\\": \\"MA==\\" },\\n      \\"totalCount\\": 302\\n    }\\n  }\\n}\\n"},{"id":"admin-catalog-products-list-filtered","title":"List Products (AND-combined filters)","description":"Filters are AND-combined — more arguments narrow the result. Here only active simple products of attribute family 1 within a price band are returned. GraphQL can also pull the relation blocks in the same single round trip on the detail query.","query":"query AdminCatalogProducts($first: Int, $status: Int, $type: String, $attribute_family: Int, $price_from: Float, $price_to: Float, $sort: String, $order: String) {\\n  adminCatalogProducts(first: $first, status: $status, type: $type, attribute_family: $attribute_family, price_from: $price_from, price_to: $price_to, sort: $sort, order: $order) {\\n    edges { node { id _id sku name type status price formattedPrice specialPrice attributeFamilyName } }\\n    pageInfo { hasNextPage endCursor }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"status\\": 1,\\n  \\"type\\": \\"simple\\",\\n  \\"attribute_family\\": 1,\\n  \\"price_from\\": 50,\\n  \\"price_to\\": 200,\\n  \\"sort\\": \\"price\\",\\n  \\"order\\": \\"asc\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCatalogProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/products/1\\",\\n            \\"_id\\": 1,\\n            \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n            \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n            \\"type\\": \\"simple\\",\\n            \\"status\\": 1,\\n            \\"price\\": \\"100.0000\\",\\n            \\"formattedPrice\\": \\"$100.00\\",\\n            \\"specialPrice\\": null,\\n            \\"attributeFamilyName\\": \\"Default\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": { \\"hasNextPage\\": false, \\"endCursor\\": \\"MA==\\" },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/index.md","filePath":"api/graphql-api/admin/catalog/products/index.md","lastUpdated":1783079210000}`),r={name:"api/graphql-api/admin/catalog/products/index.md"};function c(i,t,n,s,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>The Products menu is the catalog&#39;s product-management surface — list, search, create, edit, copy, and delete products, plus manage each product&#39;s images, per-source inventory, and customer-group prices. It mirrors the admin <strong>Catalog → Products</strong> screen.</p><h2 id="product-types" tabindex="-1">Product types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product types&quot;">​</a></h2><p>Every product has a <code>type</code>, fixed at creation. There are seven:</p><table tabindex="0"><thead><tr><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>simple</code></td><td>A standalone product with its own price and stock.</td></tr><tr><td><code>virtual</code></td><td>Like simple but non-shippable (no weight/dimensions) — services, memberships.</td></tr><tr><td><code>downloadable</code></td><td>Sells downloadable <strong>links</strong> (paid files) and <strong>samples</strong> (free previews); non-stockable.</td></tr><tr><td><code>grouped</code></td><td>A storefront grouping of other simple products (<strong>linked products</strong>); has no own price.</td></tr><tr><td><code>bundle</code></td><td>A configurable kit built from <strong>bundle options</strong>; its price is calculated from the chosen items.</td></tr><tr><td><code>configurable</code></td><td>A parent with <strong>variants</strong> generated from variant-defining attributes (<code>super_attributes</code>, e.g. colour × size). Each variant is its own SKU with its own price/stock.</td></tr><tr><td><code>booking</code></td><td>A bookable product (default / appointment / event / rental / table sub-types) with time slots; non-stockable.</td></tr></tbody></table><p><strong>Composite types own no price or stock of their own.</strong> For <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, and <code>booking</code>, the price and inventory live on the children — the variants, bundle items, linked products, or slots. Their top-level <code>price</code> / <code>quantity</code> are derived or empty.</p><h2 id="creating-a-product-is-two-steps" tabindex="-1">Creating a product is two steps <a class="header-anchor" href="#creating-a-product-is-two-steps" aria-label="Permalink to &quot;Creating a product is two steps&quot;">​</a></h2><p>Creation is deliberately minimal: <code>createAdminCatalogProduct</code> creates the shell from just <code>sku</code> + <code>attributeFamilyId</code> + <code>type</code> (plus <code>superAttributes</code> for <code>configurable</code>). Everything else — name, description, price, images, categories, channels, inventory — is filled in afterwards via <code>updateAdminCatalogProduct</code>. This mirrors the admin&#39;s create-then-edit wizard.</p><h2 id="status-vs-visibleindividually" tabindex="-1"><code>status</code> vs <code>visibleIndividually</code> <a class="header-anchor" href="#status-vs-visibleindividually" aria-label="Permalink to &quot;`status` vs `visibleIndividually`&quot;">​</a></h2><p>Two independent flags control storefront presence:</p><ul><li><strong><code>status</code></strong> — <code>1</code> enabled / <code>0</code> disabled. A disabled product is fully hidden from the storefront.</li><li><strong><code>visibleIndividually</code></strong> — whether the product appears in category/search listings. Variant products and grouped-component products are usually set to <code>0</code> (reachable only through their parent), while still being <code>status = 1</code>.</li></ul><p>Both must effectively be on for a product to be browsable on its own.</p><h2 id="nested-data-is-returned-whole" tabindex="-1">Nested data is returned whole <a class="header-anchor" href="#nested-data-is-returned-whole" aria-label="Permalink to &quot;Nested data is returned whole&quot;">​</a></h2><p>On the single-product query, nested blocks (<code>translations</code>, <code>images</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, and the type-specific blocks like <code>variants</code> / <code>bundleOptions</code> / <code>downloadableLinks</code>) are returned as <strong>whole JSON</strong> — query each as a bare field (<code>translations</code>, not <code>translations { … }</code>); the entire array comes back. They resolve over GraphQL on the detail query.</p><h2 id="per-product-sub-resources" tabindex="-1">Per-product sub-resources <a class="header-anchor" href="#per-product-sub-resources" aria-label="Permalink to &quot;Per-product sub-resources&quot;">​</a></h2><p>The product edit screen&#39;s tabs map to their own operations, each scoped to one product:</p><ul><li><strong>Images</strong> — upload (REST only — binary), reorder, and delete a product&#39;s images.</li><li><strong>Inventories</strong> — read and bulk-update the per-inventory-source stock quantities.</li><li><strong>Customer-group prices</strong> — tiered prices that apply to specific customer groups.</li></ul><p>These are not returned in full on the listing (they&#39;re detail-only); the single-product query embeds them inline.</p><h2 id="the-product-listing" tabindex="-1">The product listing <a class="header-anchor" href="#the-product-listing" aria-label="Permalink to &quot;The product listing&quot;">​</a></h2><p><code>adminCatalogProducts</code> is the datagrid query — cursor pagination via <code>first</code> / <code>after</code>. Every scalar field (including the special-price columns) <strong>resolves over GraphQL</strong>.</p><h3 id="listing-arguments-filters-are-and-combined" tabindex="-1">Listing arguments (filters are AND-combined) <a class="header-anchor" href="#listing-arguments-filters-are-and-combined" aria-label="Permalink to &quot;Listing arguments (filters are AND-combined)&quot;">​</a></h3><p>All filter arguments are <strong>combined with AND</strong> — every one you add <strong>narrows</strong> the result set:</p><table tabindex="0"><thead><tr><th>Arg</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code> / <code>after</code></td><td>cursor pagination</td><td>Page size (default <code>10</code>, max <code>50</code>) + cursor from a previous <code>pageInfo.endCursor</code>.</td></tr><tr><td><code>channel</code></td><td><code>String</code></td><td>Channel code used to resolve per-channel values.</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Partial product-name match.</td></tr><tr><td><code>sku</code></td><td><code>String</code></td><td>Partial SKU match.</td></tr><tr><td><code>attribute_family</code></td><td><code>Int</code></td><td>Attribute-family ID.</td></tr><tr><td><code>price_from</code> / <code>price_to</code></td><td><code>Float</code></td><td>Price band (inclusive).</td></tr><tr><td><code>product_id</code></td><td><code>String</code></td><td>A single ID, or a comma-separated list (e.g. <code>&quot;1,22,2705&quot;</code>).</td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>0</code> (disabled) or <code>1</code> (active).</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>One of the seven product types.</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code used to resolve translated values.</td></tr><tr><td><code>sort</code></td><td><code>String</code></td><td><code>product_id</code> (default), <code>sku</code>, <code>name</code>, <code>type</code>, <code>status</code>, <code>price</code>, <code>quantity</code>, <code>attribute_family</code>, <code>channel</code>.</td></tr><tr><td><code>order</code></td><td><code>String</code></td><td><code>asc</code> or <code>desc</code> (default <code>desc</code>).</td></tr></tbody></table><h3 id="listing-node-fields" tabindex="-1">Listing node fields <a class="header-anchor" href="#listing-node-fields" aria-label="Permalink to &quot;Listing node fields&quot;">​</a></h3><p>Each <code>node</code> carries these scalar columns. <strong>Heavy fields are <code>null</code> on the listing</strong> (query them on the <a href="/api/graphql-api/admin/catalog/products/products-detail.html">detail query</a>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>IRI (<code>/api/admin/catalog/products/{id}</code>).</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Numeric product ID.</td></tr><tr><td><code>sku</code></td><td><code>String</code></td><td>SKU.</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Resolved for the active locale/channel. <code>null</code> for draft products.</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td>Product type.</td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>1</code> active / <code>0</code> disabled.</td></tr><tr><td><code>price</code> / <code>formattedPrice</code></td><td><code>String</code></td><td>Base price (composite types carry no own price → <code>null</code>).</td></tr><tr><td><code>specialPrice</code> / <code>formattedSpecialPrice</code></td><td><code>String</code></td><td>Discounted price, when set.</td></tr><tr><td><code>specialPriceFrom</code> / <code>specialPriceTo</code></td><td><code>String</code></td><td>Special-price window (<code>null</code> = always on / no end).</td></tr><tr><td><code>quantity</code></td><td><code>Int</code></td><td>Total stock across inventory sources.</td></tr><tr><td><code>baseImageUrl</code></td><td><code>String</code></td><td>Medium-cache base image URL.</td></tr><tr><td><code>imagesCount</code></td><td><code>Int</code></td><td>Number of images.</td></tr><tr><td><code>categoryId</code> / <code>categoryName</code></td><td><code>Int</code> / <code>String</code></td><td>Primary category.</td></tr><tr><td><code>channel</code> / <code>locale</code></td><td><code>String</code></td><td>Resolved channel / locale.</td></tr><tr><td><code>attributeFamilyId</code> / <code>attributeFamilyName</code></td><td><code>Int</code> / <code>String</code></td><td>Attribute family.</td></tr><tr><td><code>urlKey</code></td><td><code>String</code></td><td>Storefront URL slug.</td></tr><tr><td><code>visibleIndividually</code> / <code>featured</code> / <code>new</code></td><td><code>Boolean</code></td><td>Storefront flags.</td></tr><tr><td><code>shortDescription</code> / <code>description</code> / <code>metaTitle</code> / <code>metaDescription</code> / <code>metaKeywords</code></td><td><code>String</code></td><td>Resolved content / SEO.</td></tr><tr><td><code>weight</code></td><td><code>Float</code></td><td>Product weight.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>String</code></td><td>Timestamps.</td></tr><tr><td><code>taxCategoryId</code> / <code>manageStock</code> / <code>inStock</code></td><td>—</td><td><strong>Detail-only</strong> — <code>null</code> on the listing.</td></tr><tr><td><code>translations</code>, <code>images</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, <code>superAttributes</code>, <code>variants</code>, <code>bundleOptions</code>, <code>linkedProducts</code>, <code>downloadableLinks</code>, <code>downloadableSamples</code></td><td>—</td><td>Relation blocks — <strong>all <code>null</code> on the listing</strong>; populated only on the <a href="/api/graphql-api/admin/catalog/products/products-detail.html">detail query</a>.</td></tr></tbody></table><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/catalog/products/copy.html">Copy</a></td><td>Duplicates an existing product into a new <strong>draft</strong> product (a fresh SKU is generated).</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/mass-delete.html">Mass delete</a></td><td>Deletes several products at once — <code>indices: [1, 22]</code>. Missing IDs are skipped.</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/mass-update-status.html">Mass update status</a></td><td>Bulk enable/disable — <code>indices: [1, 22], value: 0</code> (<code>0</code> = disable, <code>1</code> = active).</td></tr><tr><td>Export (CSV)</td><td>The datagrid &quot;Export&quot; button is <strong>REST only</strong> (binary file streams aren&#39;t expressible over GraphQL) — see <a href="/api/rest-api/admin/catalog/products/export.html">Export Products</a>.</td></tr></tbody></table><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/catalog/products.html">List products</a></td><td><code>adminCatalogProducts</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/products-detail.html">Product detail</a></td><td><code>adminCatalogProduct(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/create.html">Create product</a></td><td><code>createAdminCatalogProduct</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/update.html">Update product</a></td><td><code>updateAdminCatalogProduct</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/delete.html">Delete product</a></td><td><code>deleteAdminCatalogProduct</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/copy.html">Copy product</a></td><td><code>createAdminCatalogProductCopy</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/mass-delete.html">Mass delete</a></td><td><code>createAdminCatalogProductMassDelete</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/mass-update-status.html">Mass update status</a></td><td><code>createAdminCatalogProductMassUpdateStatus</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/images-upload.html">Upload images</a></td><td>REST only (binary)</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/images-reorder.html">Reorder images</a></td><td><code>reorderAdminCatalogProductImage</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/images-delete.html">Delete image</a></td><td><code>deleteAdminCatalogProductImage</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/inventories-list.html">List inventories</a></td><td><code>adminCatalogProductInventories</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/inventories-update.html">Update inventories</a></td><td><code>updateAdminCatalogProductInventory</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/customer-group-prices-list.html">List customer-group prices</a></td><td><code>adminCatalogProductCustomerGroupPrices</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/customer-group-prices-create.html">Add customer-group price</a></td><td><code>createAdminCatalogProductCustomerGroupPrice</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/customer-group-prices-update.html">Update customer-group price</a></td><td><code>updateAdminCatalogProductCustomerGroupPrice</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/products/customer-group-prices-delete.html">Delete customer-group price</a></td><td><code>deleteAdminCatalogProductCustomerGroupPrice</code> mutation</td></tr></tbody></table><p>The canonical product listing is <a href="/api/graphql-api/admin/catalog/products.html">List products</a> (<code>adminCatalogProducts</code> query) above. There is also a separate slim <a href="/api/graphql-api/admin/catalog/products/list.html">Add-Product Search</a> (<code>adminProducts</code> query) used only by the Create-Order &quot;Add Product&quot; modal — not the product listing.</p><p>All Products operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.products.view</code>; writes require the matching <code>catalog.products.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',32)]))}const m=e(r,[["render",c]]);export{h as __pageData,m as default};
